function pimpinanCanAccess(user, audit, profiles) {
  const p = profiles.find(row => yes(row.Active) && text(row.PimpinanID) === text(user.RefID));
  if (!p || !text(user.RefID)) return false;
  const level = upper(p.Level), area = text(p.AccessID || p.UnitID);
  return ['UNIVERSITAS','YAYASAN'].includes(level) || (level === 'FAKULTAS' && text(p.AccessName || area) && upper(audit.Fakultas) === upper(p.AccessName || area)) || (level === upper(audit.AuditiType) && area && area === text(audit.AuditiID));
}
function assertImportAccess(user, module, context, data) {
  const audit = assertAccess(user, module, context, data);
  if (EXPORT_ONLY.has(module) || module === 'AUDIT_REKAP') throw new Error('Modul ini hanya dapat diekspor.');
  if (AUDIT_ROLES[module] && upper(user.Role) !== AUDIT_ROLES[module]) throw new Error('Role Anda tidak dapat mengimpor modul ini.');
  const states = {EVALUASI_DIRI:['PENUGASAN DITERBITKAN','EVALUASI DIRI BERJALAN','PERLU REVISI AUDITI'], DESK_EVALUATION:['EVALUASI DIRI DIKIRIM','DESK EVALUATION','SIAP VISITASI','VISITASI BERJALAN','HASIL AUDIT DIISI','PERLU REVISI AUDITOR'], HASIL_AUDIT:['SIAP VISITASI','VISITASI BERJALAN','HASIL AUDIT DIISI','PERLU REVISI AUDITOR'], TINDAK_LANJ:['MENUNGGU ACC AUDITI']};
  if (audit) {
    const status = upper(audit.Status || '');
    const allowed = states[module] || states.DESK_EVALUATION || [];
    if (status === 'FINAL' || (status && !allowed.includes(status))) throw new Error('Import terkunci pada status audit ini.');
  }
}
async function applyRow(db, schema, module, context, row, user, data) {
  const value = key => text(get(row, key));
  if (TABLES[module]) {
    const name = TABLES[module], key = {MASTER_PRODI:'ProdiID',MASTER_UNIT:'UnitID',MASTER_AUDITOR:'AuditorID',MASTER_PIMPINAN:'PimpinanID',MASTER_STANDAR:'StandardID',SIKLUS:'CycleID'}[module];
    const matchFields = {MASTER_PRODI:['KodeProdi'],MASTER_UNIT:['KodeUnit'],MASTER_AUDITOR:['NIDN_NIK'],MASTER_PIMPINAN:['Nama','Jabatan'],MASTER_STANDAR:['ItemCode','Versi'],SIKLUS:['NamaSiklus','Tahun']}[module];
    const existing = data[name].find(item => matchFields.every(field => upper(item[field] || (field === 'Versi' ? '1.0' : '')) === upper(value(field) || (field === 'Versi' ? '1.0' : ''))) && matchFields.some(field => value(field)));
    const input = {...row, [key]:existing?.[key], Active:yes(get(row,'Active'))};
    if (module === 'MASTER_STANDAR') await localAdmin.saveStandard(db,schema,user,input);
    else if (module === 'SIKLUS') await localAdmin.saveCycle(db,schema,user,input);
    else { if(module==='MASTER_PIMPINAN') Object.assign(input,{AccessName:value('AreaAkses'),AccessID:value('AreaAkses'),AccessType:value('Level')}); await localAdmin.saveMaster(db,schema,user,module.replace('MASTER_',''),input); }
    data[name] = (await db.query(`SELECT * FROM ${table(schema,name)}`)).rows;
    return {mode:existing ? 'updated' : 'imported'};
  }
  if (['PENETAPAN_STANDAR','TIM_AUDITOR'].includes(module)) {
    const master = (upper(value('AuditiType')) === 'PRODI' ? data.MASTER_PRODI : data.MASTER_UNIT) || [];
    const hit = master.find(x => [x.ProdiID,x.UnitID,x.KodeProdi,x.KodeUnit].map(text).includes(value('KodeAuditi')));
    const audit = data.AMI_AUDITI.find(x => text(x.CycleID) === text(context.cycleId) && upper(x.AuditiType) === upper(value('AuditiType')) && (text(x.AuditiID) === text(hit?.ProdiID || hit?.UnitID || value('KodeAuditi')) || upper(x.AuditiName) === upper(value('NamaAuditi'))));
    if (!audit) throw new Error('Auditi tidak ditemukan pada siklus ini.');
    if (module === 'TIM_AUDITOR') {
      const find = key => data.MASTER_AUDITOR.find(x => text(x.NIDN_NIK) === value(key))?.AuditorID;
      await localAdmin.saveAuditTeamsBatch(db,schema,user,[{AuditID:audit.AuditID,LeadAuditorID:find('LeadNIDN_NIK'),Member1ID:find('Anggota1NIDN_NIK'),Member2ID:find('Anggota2NIDN_NIK')}]);
    } else {
      const standard = data.MASTER_STANDAR.find(x => upper(x.ItemCode) === upper(value('ItemCode')) && text(x.Versi || '1.0') === (value('VersiStandar') || '1.0'));
      if (!standard) throw new Error('Standar tidak ditemukan.');
      await localAdmin.assignStandards(db,schema,user,[audit.AuditID],[standard.StandardID],false);
    }
    return {mode:'imported'};
  }
  const auditId = context.auditId;
  if (module === 'VISITASI') { await localWorkflow.saveAllVisitForms(db,schema,user,auditId,{visit:row}); return {mode:'updated'}; }
  if (module === 'FORM2' || module === 'FORM3') {
    const payload = module === 'FORM2' ? {form2:{Program:buildPrograms(data,auditId,row)}} : {form3:{Catatan:buildNotes(data,auditId,row)}};
    await localWorkflow.saveAllVisitForms(db,schema,user,auditId,payload); return {mode:'updated'};
  }
  const assignment = assignmentFor(data,auditId,row);
  if (!assignment) throw new Error('ItemCode dan versi tidak ditugaskan pada audit ini.');
  const item = {...row,AssignID:assignment.AssignID,StandardID:assignment.StandardID,NilaiCapaian:value('NilaiAktual'),ButuhVisitasi:yes(get(row,'ButuhVisitasi'))};
  const handlers = {EVALUASI_DIRI:'saveAllSelfEvaluation',DESK_EVALUATION:'saveAllDeskEvaluation',HASIL_AUDIT:'saveAllFindings',TINDAK_LANJ:'saveAllAuditiFollowUps'};
  if (module === 'TINDAK_LANJ') item.FindingID = data.FINDINGS.find(x => text(x.AssignID) === text(assignment.AssignID))?.FindingID;
  await localWorkflow[handlers[module]](db,schema,user,auditId,[item]);
  if (module === 'EVALUASI_DIRI') {
    const links=[];for(let i=1;i<=5;i++) if(value(`LinkBukti${i}`)) links.push({AssignID:assignment.AssignID,URL:value(`LinkBukti${i}`),NamaBukti:value(`NamaBukti${i}`)});
    if(links.length) await localWorkflow.saveEvidenceLinksBatch(db,schema,user,auditId,links);
  }
  return {mode:'updated',assignId:assignment.AssignID};
}

function cancelImportXlsx(user, importToken) { const job=jobs.get(importToken); if(job && job.userId===user.UserID) jobs.delete(importToken); return {ok:true}; }
